	fmt.Fprintf(flag.CommandLine.Output(), "usage: bench [flags] <family> [family...]\n\n")
	printFamilies(flag.CommandLine.Output())
	fmt.Fprintf(flag.CommandLine.Output(), "\nflags:\n")
	flag.PrintDefaults()
}

